package test;

import org.eclipse.core.resources.ResourcesPlugin;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.ILog;
import org.eclipse.core.runtime.Status;

public class Example {
    private ILog log;

    public Example(ILog log) {
        this.log = log;
    }

    public void foo() {
        try {
            // Simulate an operation that might throw CoreException
            throw new CoreException(new Status(IStatus.ERROR, ResourcesPlugin.PI_RESOURCES, "Simulated error"));
        } catch (CoreException e) {
            log.log(new Status(IStatus.ERROR, ResourcesPlugin.PI_RESOURCES, e.getMessage(), e));
        }
    }
}

