package test;

import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.Status;
import org.eclipse.core.runtime.ILog;
import org.eclipse.core.resources.ResourcesPlugin;

public class NegativeExample {
    private ILog log;

    public NegativeExample(ILog log) {
        this.log = log;
    }

    public void bar() {
        // Different Status constructor usage, should not match
        Status customStatus = new Status(IStatus.WARNING, "my.plugin.id", "Custom warning message");
        log.log(customStatus);

        // Not a Status constructor, should not match
        String errorMessage = "Error: " + System.currentTimeMillis();
        System.err.println(errorMessage);
    }
}
